-- LOC-2: one list of places. locations become state -> lga -> area, with a `serviceable` flag and stored ancestors;
-- requests and providers point at location ids and the name columns are dropped.
-- Provider names that match no place are dropped (a city that matches nothing leaves location_id null; an unmatched
-- service area is not added). The provider must pick them again from the list.

-- Kinds: city -> state, district -> area, lga is new. The enum is replaced rather than extended so the new values can be
-- used in this same migration.
CREATE TYPE "LocationKind_new" AS ENUM ('state', 'lga', 'area');

ALTER TABLE "locations"
    -- squawk-ignore changing-column-type
    ALTER COLUMN "kind" TYPE "LocationKind_new"
    USING (CASE "kind"::text WHEN 'city' THEN 'state' ELSE 'area' END)::"LocationKind_new";

-- squawk-ignore ban-drop-type
DROP TYPE "LocationKind";
-- squawk-ignore renaming-object
ALTER TYPE "LocationKind_new" RENAME TO "LocationKind";

ALTER TABLE "locations"
    ADD COLUMN "serviceable" BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN "ancestor_ids" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];

-- The old managed city is the state FCT; its districts move under Abuja Municipal (Kubwa under Bwari) below.
UPDATE "locations"
SET "name" = 'FCT',
    "aliases" = ARRAY['Abuja (FCT)', 'Federal Capital Territory']::TEXT[],
    "serviceable" = true,
    "sort" = 14,
    "updated_at" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-4000-8000-000000000001';

-- Every other state, every LGA, and each state capital that is not also an LGA name. Ids are deterministic so the
-- list can be re-derived: md5('loc:' || state) or md5('loc:' || state || ':' || lga), with the version nibble set to 4
-- and the variant nibble to 8 so the ids pass @IsUUID().
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Launch coverage: FCT, Abuja Municipal, Bwari and the Abuja areas.
UPDATE "locations"
SET "serviceable" = true, "updated_at" = CURRENT_TIMESTAMP
WHERE "id" IN (
    overlay(overlay(md5('loc:FCT:Abuja Municipal') placing '4' from 13) placing '8' from 17)::uuid::text,
    overlay(overlay(md5('loc:FCT:Bwari') placing '4' from 13) placing '8' from 17)::uuid::text
);

UPDATE "locations"
SET "parent_id" = overlay(overlay(md5('loc:FCT:Bwari') placing '4' from 13) placing '8' from 17)::uuid::text,
    "serviceable" = true,
    "updated_at" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-4000-8000-000000000009';

UPDATE "locations"
SET "parent_id" = overlay(overlay(md5('loc:FCT:Abuja Municipal') placing '4' from 13) placing '8' from 17)::uuid::text,
    "serviceable" = true,
    "updated_at" = CURRENT_TIMESTAMP
WHERE "kind" = 'area'
  AND "parent_id" = '00000000-0000-4000-8000-000000000001';

-- "Other / not listed" is retired; a customer who is not in a listed area stops at the LGA.
UPDATE "locations"
SET "active" = false, "serviceable" = false, "updated_at" = CURRENT_TIMESTAMP
WHERE "id" = '00000000-0000-4000-8000-000000000016';

WITH RECURSIVE "tree" AS (
    SELECT "id", ARRAY[]::TEXT[] AS "ancestors"
    FROM "locations"
    WHERE "parent_id" IS NULL
    UNION ALL
    SELECT "l"."id", "tree"."ancestors" || "l"."parent_id"
    FROM "locations" "l"
    JOIN "tree" ON "l"."parent_id" = "tree"."id"
)
UPDATE "locations"
SET "ancestor_ids" = "tree"."ancestors"
FROM "tree"
WHERE "locations"."id" = "tree"."id";

-- service_requests: one location_id (the old district) replaces city_id and district_id.
ALTER TABLE "service_requests" ADD COLUMN "location_id" TEXT;

UPDATE "service_requests" SET "location_id" = "district_id";

-- squawk-ignore adding-not-nullable-field
ALTER TABLE "service_requests" ALTER COLUMN "location_id" SET NOT NULL;

ALTER TABLE "service_requests"
    -- squawk-ignore constraint-missing-not-valid,adding-foreign-key-constraint
    ADD CONSTRAINT "service_requests_location_id_fkey"
    FOREIGN KEY ("location_id") REFERENCES "locations"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

-- squawk-ignore require-concurrent-index-deletion
DROP INDEX "service_requests_service_district_id_created_at_idx";
CREATE INDEX "service_requests_service_location_id_created_at_idx"
    ON "service_requests"("service", "location_id", "created_at");

-- squawk-ignore ban-drop-column
ALTER TABLE "service_requests" DROP COLUMN "city_id", DROP COLUMN "district_id";

-- provider_profiles: city_id becomes location_id (an LGA).
-- squawk-ignore renaming-column
ALTER TABLE "provider_profiles" RENAME COLUMN "city_id" TO "location_id";
ALTER TABLE "provider_profiles"
    -- squawk-ignore renaming-object
    RENAME CONSTRAINT "provider_profiles_city_id_fkey" TO "provider_profiles_location_id_fkey";

-- A profile that pointed at the old managed city pointed at the capital area, which is the Abuja Municipal LGA.
UPDATE "provider_profiles"
SET "location_id" = overlay(overlay(md5('loc:FCT:Abuja Municipal') placing '4' from 13) placing '8' from 17)::uuid::text
WHERE "location_id" = '00000000-0000-4000-8000-000000000001';

-- location_id must be an LGA; any other managed city a profile pointed at is matched by name below instead.
UPDATE "provider_profiles"
SET "location_id" = NULL
WHERE "location_id" IS NOT NULL
  AND "location_id" NOT IN (SELECT "id" FROM "locations" WHERE "kind" = 'lga');

-- One row per name or alias of each place, lower-cased, to match free-text provider names against.
CREATE TEMP TABLE "tmp_location_names" AS
SELECT "l"."id" AS "location_id", "l"."kind"::text AS "kind", "l"."parent_id", "l"."ancestor_ids", "l"."active",
       lower(btrim("k")) AS "key"
FROM "locations" "l"
CROSS JOIN LATERAL unnest(ARRAY["l"."name"] || "l"."aliases") AS "k";

-- (b) the LGA named like `city` inside `state`, when exactly one matches.
UPDATE "provider_profiles" "p"
SET "location_id" = "m"."id"
FROM (
    SELECT "p2"."id" AS "profile_id", min("n"."location_id") AS "id"
    FROM "provider_profiles" "p2"
    JOIN "tmp_location_names" "s" ON "s"."kind" = 'state' AND "s"."key" = lower(btrim("p2"."state"))
    JOIN "tmp_location_names" "n"
      ON "n"."kind" = 'lga' AND "n"."parent_id" = "s"."location_id" AND "n"."key" = lower(btrim("p2"."city"))
    WHERE "p2"."location_id" IS NULL
    GROUP BY "p2"."id"
    HAVING count(DISTINCT "n"."location_id") = 1
) "m"
WHERE "p"."id" = "m"."profile_id";

-- (c) the LGA named like `city` anywhere, when only one state has that name.
UPDATE "provider_profiles" "p"
SET "location_id" = "m"."id"
FROM (
    SELECT "p2"."id" AS "profile_id", min("n"."location_id") AS "id"
    FROM "provider_profiles" "p2"
    JOIN "tmp_location_names" "n" ON "n"."kind" = 'lga' AND "n"."key" = lower(btrim("p2"."city"))
    WHERE "p2"."location_id" IS NULL
    GROUP BY "p2"."id"
    HAVING count(DISTINCT "n"."location_id") = 1
) "m"
WHERE "p"."id" = "m"."profile_id";

-- Service areas: each name is added when it matches one active place, looked up in the provider's state first and
-- then anywhere. Names that match nothing, or more than one place, are dropped.
CREATE TEMP TABLE "tmp_provider_area_matches" AS
WITH "provider_state" AS (
    SELECT "p"."id" AS "profile_id",
           COALESCE(
               (SELECT "ancestor_ids"[1] FROM "locations" WHERE "id" = "p"."location_id"),
               (SELECT min("location_id") FROM "tmp_location_names"
                WHERE "kind" = 'state' AND "key" = lower(btrim("p"."state")))
           ) AS "state_id"
    FROM "provider_profiles" "p"
),
"area_names" AS (
    SELECT "p"."id" AS "profile_id", "a"."name", "a"."ord"
    FROM "provider_profiles" "p"
    CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof("p"."service_areas") = 'array' THEN "p"."service_areas" ELSE '[]'::jsonb END
    ) WITH ORDINALITY AS "a"("name", "ord")
)
SELECT "n"."profile_id", "n"."ord",
       CASE WHEN "st"."cnt" > 0 THEN (CASE WHEN "st"."cnt" = 1 THEN "st"."id" END)
            WHEN "gl"."cnt" = 1 THEN "gl"."id" END AS "location_id"
FROM "area_names" "n"
LEFT JOIN "provider_state" "ps" ON "ps"."profile_id" = "n"."profile_id"
CROSS JOIN LATERAL (
    SELECT count(DISTINCT "t"."location_id") AS "cnt", min("t"."location_id") AS "id"
    FROM "tmp_location_names" "t"
    WHERE "t"."active" AND "t"."key" = lower(btrim("n"."name")) AND "ps"."state_id" IS NOT NULL
      AND ("t"."location_id" = "ps"."state_id" OR "ps"."state_id" = ANY("t"."ancestor_ids"))
) "st"
CROSS JOIN LATERAL (
    SELECT count(DISTINCT "t"."location_id") AS "cnt", min("t"."location_id") AS "id"
    FROM "tmp_location_names" "t"
    WHERE "t"."active" AND "t"."key" = lower(btrim("n"."name"))
) "gl";

UPDATE "provider_profiles" "p"
SET "service_area_ids" = (
    SELECT COALESCE(array_agg("d"."id" ORDER BY "d"."first_pos"), ARRAY[]::TEXT[])
    FROM (
        SELECT "u"."id", min("u"."pos") AS "first_pos"
        FROM (
            SELECT "x" AS "id", "o" AS "pos" FROM unnest("p"."service_area_ids") WITH ORDINALITY AS "e"("x", "o")
            UNION ALL
            SELECT "m"."location_id", 1000000 + "m"."ord"
            FROM "tmp_provider_area_matches" "m"
            WHERE "m"."profile_id" = "p"."id" AND "m"."location_id" IS NOT NULL
        ) "u"
        GROUP BY "u"."id"
    ) "d"
)
WHERE EXISTS (
    SELECT 1 FROM "tmp_provider_area_matches" "m"
    WHERE "m"."profile_id" = "p"."id" AND "m"."location_id" IS NOT NULL
);

-- Scratch tables created earlier in this migration.
-- squawk-ignore ban-drop-table
DROP TABLE "tmp_provider_area_matches";
-- squawk-ignore ban-drop-table
DROP TABLE "tmp_location_names";

-- squawk-ignore ban-drop-column
ALTER TABLE "provider_profiles" DROP COLUMN "city", DROP COLUMN "state", DROP COLUMN "service_areas";
